import{_ as d,o as e,c as s,ag as a}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"MovJOffsetC 关节空间偏移运动指令（常量版）","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovJOffsetC.md","filePath":"3. 指令/1. 运动指令/MovJOffsetC.md","lastUpdated":1778862643000}'),i={name:"3. 指令/1. 运动指令/MovJOffsetC.md"};function o(r,t,n,h,l,c){return e(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="movjoffsetc-关节空间偏移运动指令-常量版" tabindex="-1">MovJOffsetC 关节空间偏移运动指令（常量版） <a class="header-anchor" href="#movjoffsetc-关节空间偏移运动指令-常量版" aria-label="Permalink to &quot;MovJOffsetC 关节空间偏移运动指令（常量版）&quot;">​</a></h1><p>关节空间偏移运动指令（常量版）。该指令的功能与 <code>MovJOffset</code> 一致，唯一的区别在于：<code>MovJOffset</code> 使用 <code>DCPOS</code> 类型变量作为增量，而 <strong>MovJOffsetC</strong> 直接使用 <strong>X、Y、Z、A 四个实数（real）常量</strong> 作为位置增量，方便在程序中直接指定具体的偏移数值。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovJOffsetC(RP, TPX, TPY, TPZ, TPA, T, Tool, Coord, [V], [B], [C], [PayLoad], [DO])</p><p>MovJOffsetC(参考点, X偏移点, Y偏移点, Z偏移点, A偏移点, 目标点, 工具, 坐标系, [速度], [平滑], [姿态], [负载], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>RP</td><td>APOS 或 CPOS 变量</td><td>坐标系下的参考基准点位置。</td><td>必填</td></tr><tr><td>TPX / TPY / TPZ / TPA</td><td>real 常量</td><td>执行指令时机器人在对应方向（X、Y、Z、A）上要移动的位置增量数值。</td><td>必填</td></tr><tr><td>T</td><td>enum（COORD / TOOL）</td><td><code>COORD</code>：参考用户坐标系。<br><code>TOOL</code>：参考工具坐标系。</td><td>必填</td></tr><tr><td>Tool</td><td>TOOL 变量</td><td>机器人执行该轨迹时使用的工具参数。</td><td>必填</td></tr><tr><td>Coord</td><td>USERCOOR 变量</td><td>机器人执行该轨迹时使用的用户坐标系。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定机器人执行时的速度。在关节空间偏移指令中，仅 SPEED 变量中的 <code>per</code> 分量有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式（无过渡、相对、绝对、缺省）。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡值。</td><td>可选，默认 C100</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的工件负载参数。</td><td>可选，默认使用当前系统中设置的负载参数</td></tr><tr><td>[DO]</td><td>string</td><td>机器人执行完该指令后可触发的 IO 操作（如 <code>SetDO</code>、<code>PulseOut</code> 等）。目前支持：<code>SetDO</code>、<code>SetAO</code>、<code>SetSimDO</code>、<code>SetSimAO</code>、<code>PulseOut</code>、<code>PulseSimOut</code>、<code>SetDO8421</code>、<code>SetSimDO8421</code>、<code>SetDIEdge</code>、<code>SetSimDIEdge</code>。</td><td>可选</td></tr></tbody></table><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovJOffsetC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, P2, P3, P4, P5, P6, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, DO1)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>系统综合分析 <strong>P2~P5</strong> 相对 <strong>P1</strong> 的各维度偏差，计算出最终坐标赋予 <strong>P6</strong>，并以 50% 的关节速度移动至 <strong>P6</strong>。</p>',13)])])}const O=d(i,[["render",o]]);export{k as __pageData,O as default};
